   "Omdat het absolute waarheden aanvaardt zonder ze eerst onderzocht te hebben",
   "Omdat “men kan niets kennen” al een stellige bewering is",
   "Omdat het op de zintuigen vertrouwt hoewel het weet dat ze soms bedriegen"
