  "fb": "Hume scheidt “ik vind het leuk” (voorkeur, niet bediscussieerbaar) van “het is goed” (oordeel, dat redenen toelaat); van het eerste naar het tweede overgaan zonder redenen te geven, betekent dat je ze verwart.",
